slots := make(chan struct{}, 8)        // at most 8 concurrent users

func handle(ctx context.Context, r Request) error {
    select {
    case slots <- struct{}{}:
        defer func() { <-slots }()      // released on every exit path
        return serve(ctx, r)
    case <-ctx.Done():
        return ctx.Err()                // shed instead of queueing forever
    }
}

